const DICTS: Record<AdminLocale, Dict> = { it, en, ru };

const AdminI18nContext = createContext<{ locale: AdminLocale; setLocale: (l: AdminLocale) => void; t: Dict } | null>(null);

export function AdminI18nProvider({ children }: { children: React.ReactNode }) {
  const [locale, setLocaleState] = useState<AdminLocale>("it");

  useEffect(() => {
    try {
      const stored = localStorage.getItem(STORAGE_KEY) as AdminLocale | null;
      if (stored && DICTS[stored]) setLocaleState(stored);
    } catch {
      // ignore
    }
  }, []);

  const setLocale = (l: AdminLocale) => {
    setLocaleState(l);
    try { localStorage.setItem(STORAGE_KEY, l); } catch { /* ignore */ }
  };

  const value = useMemo(() => ({ locale, setLocale, t: DICTS[locale] }), [locale]);

  return <AdminI18nContext.Provider value={value}>{children}</AdminI18nContext.Provider>;
}

export function useAdminI18n() {
  const ctx = useContext(AdminI18nContext);
  if (!ctx) throw new Error("useAdminI18n must be used within AdminI18nProvider");
  return ctx;
}
